import java.util.function.Function;

public class TextPipelineBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        checkCall("a chained pipeline runs in order", "HELLO-THERE", () -> new TextPipelineBuilder()
                .add(String::trim)
                .add(s -> s.replace(" ", "-"))
                .add(String::toUpperCase)
                .build()
                .apply("  hello there  "));

        checkCall("order matters", "--hello-there--", () -> new TextPipelineBuilder()
                .add(s -> s.replace(" ", "-"))
                .add(String::trim)
                .build()
                .apply("  hello there  "));

        checkCall("an empty builder returns the input unchanged", "  as is  ",
                () -> new TextPipelineBuilder().build().apply("  as is  "));

        TextPipelineBuilder builder = new TextPipelineBuilder();
        check("stepCount starts at 0", 0, builder.stepCount());
        checkCall("add returns the same builder", true, () -> builder.add(String::trim) == builder);
        check("stepCount after one add", 1, builder.stepCount());

        checkCall("a built function ignores later steps", "trimmed", () -> {
            TextPipelineBuilder b = new TextPipelineBuilder().add(String::trim);
            Function<String, String> built = b.build();
            b.add(String::toUpperCase);
            return built.apply("  trimmed  ");
        });

        checkCall("one step is enough", "ab", () -> new TextPipelineBuilder()
                .add(s -> s + "b")
                .build()
                .apply("a"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

