import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.UnaryOperator;

public class TextPipelineBuilder {

    private final List<UnaryOperator<String>> steps = new ArrayList<>();

    public TextPipelineBuilder add(UnaryOperator<String> step) {
        steps.add(step);
        return this;
    }

    public int stepCount() {
        return steps.size();
    }

    public Function<String, String> build() {
        List<UnaryOperator<String>> snapshot = new ArrayList<>(steps);
        return text -> {
            String current = text;
            for (UnaryOperator<String> step : snapshot) {
                current = step.apply(current);
            }
            return current;
        };
    }
}
